// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"airdrop":{"slug":"airdrop","cat":"basics","en":"Airdrop","contentLocale":"en","term":"Airdrop","aka":["crypto airdrop","token airdrop"],"short":"An airdrop is a distribution of free tokens to wallet addresses or exchange users, usually to reward early users, decentralize ownership or promote a new project.","body":[["Projects run airdrops in different ways. Some take a snapshot of wallets that used their protocol before a certain date and let those wallets claim tokens. Others reward holders of an existing coin, or distribute tokens to exchange users who complete tasks or join a program such as a ",["launchpool","launchpool"],"."],["Real airdrops have been valuable, which is exactly why fake ones are everywhere. Scammers send worthless tokens to your wallet or post claim links on social media. Visiting the link and connecting your wallet can trigger a ",["token approval","token-approval"]," or signature that lets them drain your assets."],["Before claiming, find the claim page through the project's official channels, check that the ",["contract","smart-contract"]," address matches, and never enter your ",["seed phrase","seed-phrase"],". Many airdropped tokens face heavy selling at launch because recipients paid nothing, and in many countries airdropped tokens may be treated as taxable income."]],"example":["Suppose a protocol announces that every wallet that made at least 5 transactions before a snapshot can claim 400 tokens. You qualify. On the claim day the token trades at 1.20 ",["USDT","usdt"],", so your allocation is worth 480 USDT. Claiming costs about 2 USDT in gas on the network used. If many recipients sell and the price drops to 0.70 USDT a week later, the same 400 tokens are worth 280 USDT."],"mistakes":["Clicking an airdrop link from a direct message or a random token in your wallet.","Signing a wallet request you do not understand while claiming.","Spending more on gas and farming activity than the eventual airdrop is worth."],"faq":[{"q":"Are crypto airdrops free money?","a":"The tokens are free to receive, but claiming can cost gas, farming can take time and money, and the value often drops after launch. Many airdrop offers are scams."},{"q":"How do I know if an airdrop is real?","a":"Check the project's official website and verified social accounts, confirm the contract address, and never connect your wallet to a site you reached from an unsolicited message."},{"q":"Should I sell an unknown token that appeared in my wallet?","a":"Be careful. Interacting with an unknown token's website or contract can be a trap. It is often safest to ignore or hide it."}],"title":"What is a crypto airdrop? Meaning and how to stay safe","description":"Learn what a crypto airdrop is, how projects distribute tokens and how to spot fake airdrop claim links.","related":[["phishing","Phishing","Phishing is a scam where attackers impersonate a trusted exchange, wallet or person to trick you into revealing login details or a seed phrase, or into signing a transaction that hands over your funds."],["token-approval","Token approval (allowance)","A token approval is a permission you sign in your wallet that lets a smart contract spend a set amount of a specific token from your address, often needed before swapping or depositing in DeFi."],["governance-token","Governance token","A governance token is a crypto token that gives holders the right to vote on a protocol's decisions, such as fee changes, upgrades and treasury spending, in proportion to the tokens they hold or delegate."],["launchpool","Launchpool","A Launchpool is an exchange program where you lock tokens you already hold, such as the exchange token or a stablecoin, for a set period to earn a new token before or around its listing."],["rug-pull","Rug pull","A rug pull is a scam where the creators of a crypto project suddenly drain its liquidity, dump their tokens or abandon it after attracting buyers, leaving the token close to worthless."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Someone says he can make you money. First, see what he wants."},"coin":null,"tool":null,"cta":false},"centralized-exchange":{"slug":"centralized-exchange","cat":"trading","en":"Centralized exchange (CEX)","contentLocale":"en","term":"Centralized exchange (CEX)","aka":["CEX","crypto exchange","exchange"],"short":"A centralized exchange (CEX) is a company-run trading platform where you deposit funds into an account and trade crypto through the exchange's order book, with the company holding custody of your assets.","body":[["Binance, OKX, Bybit, Bitget, Coinbase and Kraken are examples of centralized exchanges. They match buyers and sellers in an ",["order book","order-book"],", offer ",["spot trading","spot-trading"]," and often futures, earn products, ",["copy trading","copy-trading"]," and fiat on-ramps. Most require ",["identity verification","kyc"]," (KYC) before you can trade or withdraw."],["The convenience comes with custody risk. When your coins sit on an exchange, the exchange controls the private keys and you hold a claim on its books. If the company is hacked, freezes withdrawals or fails, you depend on its reserves and on the law where it operates. ",["Proof of reserves","proof-of-reserves"]," reports, licensing and a long track record help you judge an exchange."],["Exchanges differ in fees, available coins, ",["liquidity","liquidity"],", supported networks, futures rules and which countries they serve. Compare maker and taker fees, withdrawal fees and order book depth for the pairs you actually trade, and check whether the exchange is permitted to serve users in your country."]],"example":"Suppose you trade 20,000 USDT of volume a month in spot. Exchange A charges 0.10 percent taker fees and Exchange B 0.08 percent. On A you pay 20 USDT a month in fees, on B 16 USDT, a difference of 48 USDT a year. If Exchange B's order book is thinner and you lose 0.05 percent more to slippage on each market order, that adds 10 USDT a month and wipes out the saving.","mistakes":["Leaving all your crypto on one exchange without considering custody risk.","Comparing exchanges only on headline fees and ignoring spreads, slippage and withdrawal fees.","Using an exchange that does not serve your country, then getting stuck at withdrawal or verification."],"faq":[{"q":"What is the difference between a CEX and a DEX?","a":"A CEX is run by a company that holds your funds and matches orders. A DEX runs on smart contracts, and you trade directly from your own wallet."},{"q":"Are centralized exchanges safe?","a":"Large, regulated exchanges with proof of reserves and strong security are safer than unknown ones, but any custodial platform carries some risk. Many people keep long-term holdings in self-custody."},{"q":"Why do exchanges require KYC?","a":"Anti-money-laundering rules in most countries require exchanges to verify customer identity before allowing trading or withdrawals."}],"title":"What is a centralized exchange (CEX)? Meaning","description":"Learn what a centralized crypto exchange is, how custody and KYC work and what to compare between exchanges.","related":[["dex","Decentralized exchange (DEX)","A decentralized exchange (DEX) is a trading platform that runs on smart contracts, letting you swap tokens directly from your own wallet without depositing funds with a company."],["kyc","KYC (know your customer)","KYC (know your customer) is the identity check that regulated exchanges and financial firms run before letting you deposit, trade or withdraw, usually with an ID document and a selfie."],["proof-of-reserves","Proof of reserves","Proof of reserves is a report in which a crypto exchange shows that the assets it holds in wallets it controls are at least equal to the balances it owes its customers."],["custodial-wallet","Custodial wallet","A custodial wallet is a crypto wallet where a third party, usually an exchange or app, holds the private keys and controls the funds on your behalf."],["maker-taker-fees","Maker and taker fees","Maker and taker fees are the two trading fee rates an exchange charges: a maker fee when your order adds liquidity to the order book, and a usually higher taker fee when your order removes it."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Where are my coins? Exchange vs wallet"},"coin":null,"tool":"/exchanges","cta":true},"support-and-resistance":{"slug":"support-and-resistance","cat":"trading","en":"Support and resistance","contentLocale":"en","term":"Support and resistance","aka":["support level","resistance level","S/R"],"short":"Support and resistance are price zones where an asset has repeatedly stopped falling (support) or stopped rising (resistance), because buying or selling interest tends to cluster there.","body":["Support forms where buyers have stepped in before, so price tends to bounce. Resistance forms where sellers have taken profit or opened shorts before, so price tends to stall. These levels often line up with previous highs and lows, round numbers like 50,000 or 100,000, and areas where a lot of volume traded.","Think of them as zones, not exact lines. Price often pokes slightly through a level before reversing. When a level finally breaks with strong volume, it can flip roles: old resistance becomes new support, and old support becomes new resistance.","Traders use these zones to plan entries, stop-losses and take-profit targets. A common approach is to place a stop-loss a little beyond a support zone rather than exactly on it, because many traders place stops at the same obvious level and those orders can be swept in a quick move."],"example":["Suppose SOL has bounced from around 140 ",["USDT","usdt"]," three times in two months and failed to break 175 USDT twice. You buy near 142 with a stop-loss at 134, just under the support zone, and a target at 172, just under resistance. Your risk is 8 USDT per coin and your potential gain is 30 USDT. If SOL later closes several days above 175, that old ceiling may start to act as support."],"mistakes":["Treating a support level as a guarantee that price cannot fall further.","Placing a stop-loss exactly on an obvious round number where many other stops sit.","Drawing dozens of lines on a chart until every price looks like a level."],"faq":[{"q":"What happens when support breaks?","a":"Price often moves quickly lower as stop-losses trigger, and the broken support can later act as resistance if price comes back up to it."},{"q":"Is support and resistance reliable in crypto?","a":"It is a useful planning tool, not a prediction. Levels fail often, especially in fast markets, so always combine them with a stop-loss and sensible position size."}],"title":"What is support and resistance? Crypto trading basics","description":"Learn what support and resistance are, how to find them on a crypto chart and how traders use them for entries and stops.","related":[["candlestick-chart","Candlestick chart","A candlestick chart is a price chart where each candle shows the open, high, low and close price of an asset over one time period."],["stop-loss","Stop-loss order","A stop-loss order is an order that automatically closes your position when the price reaches a level you set, limiting how much you can lose on a trade."],["limit-order","Limit order","A limit order is an instruction to buy or sell only at a specific price or better, so a buy limit fills at your price or lower and a sell limit fills at your price or higher."],["all-time-high","All-time high (ATH)","An all-time high (ATH) is the highest price an asset has ever reached in its trading history, and the opposite, the lowest price ever, is called an all-time low (ATL)."]],"lesson":{"id":"E15","slug":"read-a-candlestick","ep":15,"title":"One candle: what four things does it tell you?"},"coin":null,"tool":null,"cta":false},"dollar-cost-averaging":{"slug":"dollar-cost-averaging","cat":"trading","en":"Dollar-cost averaging (DCA)","contentLocale":"en","term":"Dollar-cost averaging (DCA)","aka":["DCA","recurring buy","auto-invest"],"short":"Dollar-cost averaging (DCA) is a strategy of buying a fixed amount of an asset at regular intervals, regardless of price, to spread your entry over time.","body":[["Instead of trying to pick the perfect moment, you invest the same amount on a schedule, for example 100 ",["USDT","usdt"]," every week. When the price is low, that amount buys more coins. When the price is high, it buys fewer. Over time your average cost per coin is smoothed out."],["DCA reduces the risk of putting everything in right before a big drop, and it removes much of the stress of timing the market. Many exchanges offer recurring buy or auto-invest features that do this automatically, usually on the ",["spot market","spot-trading"],"."],"DCA does not guarantee a profit. If the asset keeps falling for years, you still lose money. In a steadily rising market, a single lump-sum purchase at the start would usually have done better. Fees also matter: very small, frequent purchases can lose a noticeable share to trading fees or spreads, so check the cost of the recurring buy feature you use."],"example":["Suppose you invest 200 USDT in ",["BTC","bitcoin"]," on the first day of four months. Prices are 50,000, 40,000, 50,000 and 62,500 USDT. You buy 0.004, 0.005, 0.004 and 0.0032 BTC, for a total of 0.0162 BTC for 800 USDT. Your average cost is 800 ÷ 0.0162 ≈ 49,383 USDT, lower than the simple average of the four prices (50,625) because the fixed amount bought more when the price was low."],"mistakes":["Believing DCA removes risk entirely, when a long decline still produces losses.","Stopping the plan during a downturn, which is exactly when DCA buys the most coins.","Using tiny daily buys where fees take a large share of each purchase."],"faq":[{"q":"Is DCA better than investing a lump sum?","a":"Not always. A lump sum often does better in a rising market, while DCA reduces the damage from bad timing. Many people choose DCA because it is easier to stick with."},{"q":"How often should I DCA into crypto?","a":"Weekly or monthly schedules are common. Pick an interval and amount you can keep up comfortably, and check that fees stay small relative to each purchase."}],"title":"What is dollar-cost averaging (DCA) in crypto?","description":"Learn how dollar-cost averaging works in crypto, how it lowers your average entry and where it can still lose money.","related":[["hodl","HODL","HODL is crypto slang for holding an asset for the long term instead of selling during price drops, originating from a misspelling of \"hold\" in a 2013 Bitcoin forum post."],["volatility","Volatility","Volatility is a measure of how much and how quickly an asset's price moves up and down over a given period, and higher volatility means larger, faster swings."],["position-sizing","Position sizing","Position sizing is deciding how much to put into a single trade so that, if your stop-loss is hit, you lose only a planned share of your account."],["grid-trading-bot","Grid trading bot","A grid trading bot is an automated tool that places a ladder of buy and sell limit orders within a price range, profiting from repeated moves up and down."],["spot-trading","Spot trading","Spot trading is buying or selling a cryptocurrency for immediate delivery at the current market price, so you actually own the coins once the trade is filled."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"Decide how much you could lose before you decide how much to buy"},"coin":null,"tool":null,"cta":true},"usdt-margined-futures":{"slug":"usdt-margined-futures","cat":"derivatives","en":"USDT-margined (linear) futures","contentLocale":"en","term":"USDT-margined (linear) futures","aka":["linear futures","USDT-M","USDT perpetual","stablecoin-margined futures"],"short":"USDT-margined (linear) futures are futures contracts where margin, profit and loss are all in the stablecoin USDT, so results move in a straight line with the price.","body":[["In a ",["USDT","usdt"],"-margined ",["contract","smart-contract"]," you post USDT as margin and every price move translates directly into USDT. A 1 USDT move on a 1 ",["BTC","bitcoin"]," position is a 1 USDT gain or loss. That simple, linear relationship is why these contracts are called linear and why most beginners start with them."],["Because one margin currency covers many markets, you can trade BTC, ",["ETH","ethereum"]," and hundreds of smaller coins from a single USDT balance. With ",["cross margin","cross-margin"],", profits on one position can support another. Some exchanges also offer ",["USDC","usdc"],"-margined contracts that work the same way."],"Your collateral does not fall with the coin, unlike inverse contracts, so a long position has only one source of risk. You still carry stablecoin risk: if USDT lost its peg, your margin would be worth less. Contract sizes, maximum leverage and fees differ by exchange and pair, so check the contract details."],"example":"Suppose you short 2 ETH on a USDT-margined perpetual at 3,200 USDT with 1,280 USDT of margin, which is 5x leverage on a 6,400 USDT position. If ETH drops to 3,000, you earn 2 × 200 = 400 USDT. If ETH rises to 3,400, you lose 2 × 200 = 400 USDT, about 31% of your margin. The same 200 USDT move always means the same 400 USDT result, whatever the price level.","mistakes":["Assuming a stablecoin margin means the position itself is low risk.","Letting one bad position drain the whole USDT balance in cross margin mode.","Mixing up USDT-margined and coin-margined versions of the same contract."],"faq":[{"q":"What is the difference between USDT-M and COIN-M futures?","a":"USDT-M contracts use USDT for margin and profit, with linear payoffs. COIN-M contracts use the coin itself, so payoffs are non-linear and the collateral moves with the price."},{"q":"Are USDT-margined futures better for beginners?","a":"They are usually easier to understand because profit and loss are simple to calculate in a stable unit. The leverage risks are the same."}],"title":"What are USDT-margined (linear) futures? Explained","description":"Learn how USDT-margined linear futures work, why profit and loss are simple to calculate and how they differ from inverse contracts.","related":[["coin-margined-futures","Coin-margined (inverse) futures","Coin-margined (inverse) futures are futures contracts where margin and profit or loss are in the underlying coin, such as BTC, instead of a stablecoin."],["perpetual-futures","Perpetual futures (perps)","Perpetual futures (perps) are futures contracts with no expiry date that use a periodic funding rate to keep their price close to the underlying spot price."],["usdt","USDT (Tether)","USDT, also called Tether, is the largest US dollar stablecoin, issued by Tether, designed to stay at 1 dollar and backed by reserves the company reports in regular attestations."],["cross-margin","Cross margin","Cross margin is a margin mode where all your open positions share the available balance in your account as collateral, so profits and spare funds can absorb losses before liquidation."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futures: you're not buying the same thing"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":true},"open-interest":{"slug":"open-interest","cat":"derivatives","en":"Open interest","contentLocale":"en","term":"Open interest","aka":["OI"],"short":"Open interest is the total number or value of derivatives contracts, such as futures or options, that are currently open and not yet closed or settled.","body":[["Every ",["futures contract","futures-contract"]," has a long side and a short side. When a new buyer and a new seller open positions, open interest rises. When both sides close, it falls. When one trader passes a position to another, it stays the same. Open interest is shown in contracts, coins or USD value."],"Open interest is different from volume. Volume counts how much traded during a period; open interest counts how much is still outstanding at a moment. A market can have huge volume with flat open interest if traders open and close positions all day.",["Traders combine open interest with price and funding. Rising price with rising open interest suggests new money is entering with ",["leverage","leverage"],". Very high open interest relative to normal levels means a lot of leverage is in the system, which can lead to large ",["liquidation","liquidation"]," cascades if price moves sharply. Data can be viewed per exchange or aggregated across many."]],"example":["Suppose ",["BTC","bitcoin"]," perpetual open interest on an exchange is 8 billion ",["USDT","usdt"],". Over two days price rises from 60,000 to 64,000 and open interest climbs to 9.5 billion, while funding rises to well above its usual level. That points to new leveraged longs. If price then drops to 61,000 and open interest falls back to 8.2 billion within hours, about 1.3 billion USDT of positions closed, many through liquidation."],"mistakes":["Confusing open interest with trading volume.","Reading rising open interest as bullish without looking at whether longs or shorts are adding.","Comparing open interest in coins on one site with open interest in USD on another."],"faq":[{"q":"Is high open interest bullish or bearish?","a":"Neither by itself. It shows how much leverage is in the market; combined with price direction and funding, it hints at who is crowded."},{"q":"Why does open interest drop suddenly?","a":"Usually because many positions closed at once, often through a wave of liquidations or traders taking profit after a big move."}],"title":"What is open interest in crypto? Meaning explained","description":"Learn what open interest measures in crypto futures, how it differs from volume and how traders read it with price and funding.","related":[["trading-volume","Trading volume","Trading volume is the total amount of an asset traded over a set period, usually shown as the 24-hour volume in coins or in USD value."],["funding-rate","Funding rate","A funding rate is a periodic payment between long and short traders that keeps a perpetual futures price close to the spot price."],["long-short-ratio","Long/short ratio","The long/short ratio compares how many traders or how much position size on an exchange is long versus short on a futures market, as a gauge of sentiment."],["liquidation","Liquidation","Liquidation is when an exchange forcibly closes your leveraged position because your margin has fallen below the maintenance margin requirement."]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"hot-wallet":{"slug":"hot-wallet","cat":"wallets-security","en":"Hot wallet","contentLocale":"en","term":"Hot wallet","aka":["online wallet","software wallet"],"short":"A hot wallet is a crypto wallet whose private keys are stored on a device connected to the internet, such as a phone app, browser extension or exchange system, which makes it convenient but more exposed to attacks.","body":[["Hot means online. A mobile wallet, a desktop app or a browser extension keeps the keys on a device that is connected to the internet, so you can send, swap and use ",["DeFi","defi"]," apps in seconds. Exchanges also run hot wallets to process customer withdrawals quickly."],["The trade-off is exposure. Malware, fake browser extensions, ",["phishing","phishing"]," sites and malicious transaction requests can all reach a device that is online. Most hot wallet losses come from the user signing something harmful or leaking the ",["seed phrase","seed-phrase"],", not from the wallet software being broken."],["A common setup is to treat a hot wallet like a physical wallet in your pocket: keep a spending amount there and keep long-term savings in a ",["cold wallet","cold-wallet"]," or ",["hardware wallet","hardware-wallet"],"."]],"example":["Say you hold 5,000 ",["USDT","usdt"]," in total. You keep 300 USDT in a browser wallet for trying new DeFi apps and leave the remaining 4,700 USDT on a hardware wallet. One day you connect to a fake airdrop site and approve a malicious request. The attacker drains the browser wallet, and you lose 300 USDT, about 6 percent of your holdings, instead of everything."],"mistakes":["Keeping long-term savings in the same browser wallet you use to test new apps and airdrops.","Installing a wallet extension from a search ad instead of from the official store listing.","Signing every pop-up without reading which contract and which amount it asks for."],"faq":[{"q":"Is a hot wallet safe?","a":"It is reasonably safe for everyday amounts if your device is clean and you check what you sign. It is not ideal for large balances you rarely touch."},{"q":"Is an exchange account a hot wallet?","a":"From your point of view it is a custodial account; the exchange holds the keys and keeps part of customer funds in its own hot wallets for withdrawals and the rest in cold storage."}],"title":"What is a hot wallet? Meaning and risks in crypto","description":"What a hot wallet is, why it is convenient, how hot wallets get drained, and how much to keep in one.","related":[["cold-wallet","Cold wallet (cold storage)","A cold wallet is a way of storing crypto where the private keys are generated and kept offline, away from internet-connected devices, so remote attackers cannot reach them."],["hardware-wallet","Hardware wallet","A hardware wallet is a small physical device that stores your private keys offline and signs transactions inside the device, so the keys never leave it even when it is plugged into a computer or phone."],["non-custodial-wallet","Non-custodial wallet (self-custody wallet)","A non-custodial wallet is a crypto wallet where you alone hold the private keys or seed phrase, so no exchange or company can move, freeze or recover your funds for you."],["phishing","Phishing","Phishing is a scam where attackers impersonate a trusted exchange, wallet or person to trick you into revealing login details or a seed phrase, or into signing a transaction that hands over your funds."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Where are my coins? Exchange vs wallet"},"coin":null,"tool":null,"cta":false},"seed-phrase":{"slug":"seed-phrase","cat":"wallets-security","en":"Seed phrase (recovery phrase)","contentLocale":"en","term":"Seed phrase (recovery phrase)","aka":["recovery phrase","mnemonic phrase","secret recovery phrase","backup phrase"],"short":"A seed phrase is a list of usually 12 or 24 ordinary words that encodes the master key of a crypto wallet, so anyone who has the words can restore the wallet and spend all of its funds.","body":["Most wallets follow the BIP-39 standard, which picks words from a fixed list of 2,048 English words. From the phrase, the wallet derives your private keys and addresses on many blockchains. The order of the words matters, and so does any optional extra passphrase you may have set.","The seed phrase is not a password you can change at a help desk. It is the wallet. No real exchange, wallet team or support agent will ever need it. Anyone asking for it, through a pop-up, a sync tool, a support chat or a giveaway, is trying to take your funds.","Store it offline, ideally on paper or metal, in more than one safe place. Do not photograph it, email it, or keep it in a password manager linked to an account that could be phished."],"example":["Suppose a wallet holds 0.5 ",["BTC","bitcoin"]," and 2,000 ",["USDT","usdt"]," across two chains, all derived from one 12-word phrase. A scammer posing as wallet support asks you to verify your wallet by entering the words into a form. Within minutes, both the 0.5 BTC and the 2,000 USDT are moved, because the attacker can now generate the same keys. With 2,048 possible words per position, guessing a 12-word phrase is practically impossible, so leaking it is the real danger."],"mistakes":["Entering the seed phrase on any website, form or chat that claims to validate or sync your wallet.","Storing the words as a phone photo or in cloud notes.","Writing the words out of order or skipping the check step when the wallet asks you to confirm them."],"faq":[{"q":"Is a seed phrase the same as a private key?","a":"No. The seed phrase is a master backup that can generate many private keys, one for each address the wallet uses."},{"q":"Can I recover my wallet without the seed phrase?","a":"Usually not. In a non-custodial wallet, nobody else holds a copy, so a lost phrase and a lost device mean lost funds."},{"q":"Does an exchange account have a seed phrase?","a":"No. A custodial exchange account is protected by your login, 2FA and the exchange itself, not by a seed phrase."}],"title":"What is a seed phrase? Recovery phrase meaning","description":"What a seed phrase is, why it controls your whole wallet, how to store it, and the scams that try to steal it.","related":[["private-key","Private key","A private key is a secret number that proves ownership of a crypto address and is used to sign transactions, so whoever holds it can spend the coins at that address."],["non-custodial-wallet","Non-custodial wallet (self-custody wallet)","A non-custodial wallet is a crypto wallet where you alone hold the private keys or seed phrase, so no exchange or company can move, freeze or recover your funds for you."],["phishing","Phishing","Phishing is a scam where attackers impersonate a trusted exchange, wallet or person to trick you into revealing login details or a seed phrase, or into signing a transaction that hands over your funds."],["hardware-wallet","Hardware wallet","A hardware wallet is a small physical device that stores your private keys offline and signs transactions inside the device, so the keys never leave it even when it is plugged into a computer or phone."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Someone says he can make you money. First, see what he wants."},"coin":null,"tool":null,"cta":false},"public-key":{"slug":"public-key","cat":"wallets-security","en":"Public key","contentLocale":"en","term":"Public key","aka":[],"short":"A public key is the shareable half of a crypto key pair, calculated from the private key, that lets the network verify your signatures and from which your wallet address is derived.","body":[["Public-key cryptography uses two linked keys. The ",["private key","private-key"]," signs, and the public key verifies. ",["Bitcoin","bitcoin"]," and ",["Ethereum","ethereum"]," use elliptic curve cryptography, where computing the public key from the private key is easy, but the reverse is not feasible."],["Your ",["wallet address","wallet-address"]," is usually a shortened, hashed version of the public key. On Ethereum, the address is the last 20 bytes of the hash of the public key. Bitcoin uses several address formats built from the public key in different ways."],"You rarely need to handle a public key directly. Some advanced tools, such as multisig setups or watch-only wallets, use an extended public key (xpub) to track every address of a wallet. An xpub cannot spend funds, but it reveals your full balance and history, so share it only with tools you trust."],"example":["Suppose Alice signs a transaction sending 0.05 BTC to Bob. Each ",["node","node"]," on the network receives the transaction, the signature and Alice's public key. It runs the verification math and confirms that only the owner of the matching private key could have produced that signature, and that the public key matches the address holding the 0.05 BTC. The private key itself never travels across the network."],"mistakes":["Believing the public key is the same thing as the wallet address in every blockchain.","Sharing an xpub with an unknown app without realising it exposes every address and balance in the wallet.","Thinking a public key can be used to move funds."],"faq":[{"q":"Is it safe to share my public key?","a":"Yes, in terms of spending. A public key cannot move funds, though it can link your addresses and reveal your activity."},{"q":"Is a public key the same as a wallet address?","a":"Not exactly. The address is usually derived from the public key by hashing and encoding it, which makes it shorter and adds error checks."}],"title":"What is a public key in crypto? Meaning explained","description":"What a public key is, how it differs from a private key and a wallet address, and what an xpub reveals.","related":[["private-key","Private key","A private key is a secret number that proves ownership of a crypto address and is used to sign transactions, so whoever holds it can spend the coins at that address."],["wallet-address","Wallet address","A wallet address is a string of letters and numbers that identifies where crypto can be sent on a specific blockchain, similar to an account number you can share publicly."],["blockchain","Blockchain","A blockchain is a shared digital ledger, copied across many computers, where transactions are grouped into blocks that are linked in order and are extremely hard to change after the fact."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Before you transfer: don't guess any of these"},"coin":null,"tool":null,"cta":false},"transaction-hash":{"slug":"transaction-hash","cat":"wallets-security","en":"Transaction hash (TxID)","contentLocale":"en","term":"Transaction hash (TxID)","aka":["TxID","TxHash","transaction ID"],"short":"A transaction hash, or TxID, is the unique identifier of a blockchain transaction, which you can paste into a block explorer to see its status, amount, addresses and confirmations.","body":[["Every transaction broadcast to a ",["blockchain","blockchain"]," gets a hash, a fixed-length string calculated from the transaction data. On ",["Ethereum","ethereum"]," it starts with 0x and has 64 hex characters after it. On ",["Bitcoin","bitcoin"]," and Tron it is a 64-character hex string."],"Exchanges show the TxID in your withdrawal history once the transfer has been sent on-chain. You can paste it into an explorer for that network, such as Etherscan, Tronscan or a Bitcoin explorer, to see whether it is pending, confirmed or failed.","The TxID is the first thing support teams ask for when a deposit is missing. It proves whether the funds left the sender and which address and network they went to. It is public information and safe to share."],"example":["Suppose you withdraw 0.03 BTC to a friend and the friend says nothing arrived after 20 minutes. You copy the TxID from your withdrawal history and paste it into a Bitcoin explorer. It shows the transaction in the ",["mempool","mempool"]," with 0 ",["confirmations","block-confirmations"]," because the fee was low. An hour later, the explorer shows 3 confirmations and the ",["receiving address","wallet-address"]," matches your friend's. The coins were never lost, only waiting for a block."],"mistakes":["Searching a TxID in an explorer for the wrong network and concluding the transaction does not exist.","Treating an exchange's internal transfer ID as an on-chain TxID.","Assuming a missing TxID means the funds left; if the exchange has not broadcast it yet, there is no hash."],"faq":[{"q":"Where do I find my transaction hash?","a":"In your exchange's withdrawal or deposit history, or in your wallet's activity list. Tap the transaction to see or copy the TxID."},{"q":"Is it safe to share a TxID?","a":"Yes. It only points to public data already on the blockchain and cannot be used to move funds."}],"title":"What is a transaction hash (TxID)? How to use one","description":"Learn what a TxID is, where to find it, and how to track a deposit or withdrawal in a block explorer.","related":[["block-explorer","Block explorer","A block explorer is a website or app that lets you search a blockchain's public records, including transactions, addresses, blocks and token transfers."],["block-confirmations","Block confirmations","Block confirmations are the number of blocks added to a blockchain since the block that includes your transaction, and exchanges wait for a set number before crediting a deposit."],["blockchain-network","Deposit network (chain selection)","A deposit network is the blockchain you choose to move a coin or token over when you deposit to or withdraw from an exchange, and the sending and receiving sides must use the same one."],["mempool","Mempool","The mempool is the waiting area where valid but unconfirmed transactions sit on network nodes until a miner or validator includes them in a block."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"It says sent, but it never arrived. Where do you look?"},"coin":null,"tool":null,"cta":false},"address-poisoning":{"slug":"address-poisoning","cat":"wallets-security","en":"Address poisoning","contentLocale":"en","term":"Address poisoning","aka":["address poisoning scam","dusting with look-alike addresses"],"short":"Address poisoning is a scam where an attacker sends a tiny or zero-value transfer from an address that looks like one you use, hoping you later copy that fake address from your transaction history.","body":[["Attackers watch the ",["blockchain","blockchain"]," for addresses you send funds to. They generate a look-alike address that matches the first and last few characters, then send you a tiny amount or a fake token transfer from it. Now the fake address sits in your history right next to the real one."],"The next time you copy an address from your history instead of the original source, you may paste the attacker's address. Because many wallets shorten addresses to the first and last characters, the two can look identical.",["Protection comes from habits: copy addresses from the original source or your address book, check more than the first and last four characters, use a ",["withdrawal whitelist","withdrawal-whitelist"]," on exchanges, and ignore unexpected tiny transfers rather than interacting with them."]],"example":["Say you regularly send ",["USDT","usdt"]," to your own address 0x7a3F...91cD. After one transfer, a 0 USDT transaction arrives from 0x7a3F...91cD, but the middle characters are different. A week later you copy the top entry from your history and send 8,000 USDT. It goes to the attacker. Checking the full address, or using a saved contact, would have shown the mismatch before you confirmed."],"mistakes":["Copying a recipient address from your recent transaction list.","Checking only the first and last four characters of an address.","Interacting with an unknown token that appeared in your wallet after a poisoning transfer."],"faq":[{"q":"Can address poisoning steal funds without my action?","a":"No. The scam only works if you send to the fake address yourself. Your existing funds are not at risk from the dust transfer alone."},{"q":"Should I hide or ignore the tiny transfer?","a":"Ignore it and do not trade or approve the token. Some wallets let you hide spam tokens, which reduces confusion."}],"title":"What is address poisoning? How the scam works","description":"How address poisoning scams plant look-alike addresses in your history, and how to check addresses before sending.","related":[["wallet-address","Wallet address","A wallet address is a string of letters and numbers that identifies where crypto can be sent on a specific blockchain, similar to an account number you can share publicly."],["withdrawal-whitelist","Withdrawal whitelist","A withdrawal whitelist is an exchange security setting that only allows withdrawals to addresses you have saved and approved in advance, blocking transfers to any new address."],["phishing","Phishing","Phishing is a scam where attackers impersonate a trusted exchange, wallet or person to trick you into revealing login details or a seed phrase, or into signing a transaction that hands over your funds."],["transaction-hash","Transaction hash (TxID)","A transaction hash, or TxID, is the unique identifier of a blockchain transaction, which you can paste into a block explorer to see its status, amount, addresses and confirmations."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Before you transfer: don't guess any of these"},"coin":null,"tool":null,"cta":false},"token-approval":{"slug":"token-approval","cat":"wallets-security","en":"Token approval (allowance)","contentLocale":"en","term":"Token approval (allowance)","aka":["token allowance","approval","approve","spending cap"],"short":"A token approval is a permission you sign in your wallet that lets a smart contract spend a set amount of a specific token from your address, often needed before swapping or depositing in DeFi.","body":[["On ",["Ethereum","ethereum"]," and other EVM chains, a ",["contract","smart-contract"]," cannot move your ERC-20 tokens unless you first call approve. The approval names the contract (the spender) and an amount, called the allowance. Many apps request an unlimited allowance so you do not have to approve again for each trade."],"Approvals stay active until you change them. If a contract you approved is later hacked or was malicious from the start, it can pull your approved tokens at any time, without another signature from you. Signature-based permits, such as Permit2, can grant similar rights through a message signature that may look harmless.",["Good practice: approve only the amount you need when the wallet lets you edit it, read the spender address, and regularly review and revoke old approvals with a revoke tool or the approvals page of a ",["block explorer","block-explorer"],"."]],"example":["Say you swap 500 ",["USDC","usdc"]," on a ",["DEX","dex"]," and approve an unlimited USDC allowance. Months later you hold 6,000 USDC in the same wallet. If that DEX contract were exploited, the attacker could take all 6,000 USDC using your old approval. If you had set the allowance to 500, the contract could not take more than the remaining allowance, which after the swap would be zero."],"mistakes":["Accepting unlimited approvals by default on apps you use only once.","Never revoking approvals given to old or abandoned projects.","Signing a permit message on an unfamiliar site because it does not look like a transaction."],"faq":[{"q":"Does revoking an approval cost gas?","a":"Yes. Revoking is an on-chain transaction, so it needs a small network fee on that chain."},{"q":"Can a token approval steal my ETH?","a":"An ERC-20 approval covers only that token. Native ETH is not moved by approvals, but signing other malicious transactions can still lose it."}],"title":"What is a token approval? Allowances explained","description":"What token approvals and allowances are, why unlimited approvals are risky, and how to review and revoke them.","related":[["smart-contract","Smart contract","A smart contract is a program stored on a blockchain that runs automatically when its conditions are met, letting people trade, lend or issue tokens without a middleman."],["phishing","Phishing","Phishing is a scam where attackers impersonate a trusted exchange, wallet or person to trick you into revealing login details or a seed phrase, or into signing a transaction that hands over your funds."],["non-custodial-wallet","Non-custodial wallet (self-custody wallet)","A non-custodial wallet is a crypto wallet where you alone hold the private keys or seed phrase, so no exchange or company can move, freeze or recover your funds for you."],["dex","Decentralized exchange (DEX)","A decentralized exchange (DEX) is a trading platform that runs on smart contracts, letting you swap tokens directly from your own wallet without depositing funds with a company."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Someone says he can make you money. First, see what he wants."},"coin":null,"tool":null,"cta":false},"dex":{"slug":"dex","cat":"defi","en":"Decentralized exchange (DEX)","contentLocale":"en","term":"Decentralized exchange (DEX)","aka":["DEX","decentralised exchange","on-chain exchange"],"short":"A decentralized exchange (DEX) is a trading platform that runs on smart contracts, letting you swap tokens directly from your own wallet without depositing funds with a company.","body":[["Most DEXs, such as Uniswap, PancakeSwap and Curve, use automated market makers: you trade against a ",["liquidity pool","liquidity-pool"],", and a formula sets the price. Others, especially perp DEXs like Hyperliquid, run an ",["order book","order-book"]," on-chain or on a dedicated chain."],["Compared with a ",["centralized exchange","centralized-exchange"],", you keep custody of your coins, any token can be listed by anyone, and there is usually no account sign-up. In exchange, you pay network gas fees, may face higher ",["slippage","slippage"]," on small tokens, and have no support team if you send a wrong transaction or buy a scam token."],["Before swapping, check the token ",["contract","smart-contract"]," address, the expected output, the price impact and your slippage setting. A high slippage tolerance can let bots sandwich your trade."]],"example":["Imagine you want to swap 1,000 ",["USDC","usdc"]," for ETH on a DEX. The interface quotes 0.330 ETH with a 0.3 percent pool fee and 0.2 percent price impact. You set slippage to 0.5 percent, so the trade fails rather than fill below about 0.328 ETH. The swap confirms and you receive 0.329 ETH plus pay a network fee of a few dollars in ETH, depending on the chain."],"mistakes":["Buying a token by name instead of verifying its contract address.","Setting a very high slippage tolerance to make a trade go through.","Comparing DEX and exchange prices without counting gas fees and price impact."],"faq":[{"q":"What is the difference between a DEX and a CEX?","a":"A CEX holds your funds and matches trades on its own servers. A DEX lets you trade directly from your wallet through smart contracts."},{"q":"Do DEXs require KYC?","a":"Most DEX contracts do not, but some front-ends block certain countries, and the token you buy can still be a scam."}],"title":"What is a DEX? Decentralized exchange explained","description":"What a decentralized exchange is, how DEX swaps work, how they differ from centralized exchanges, and what to check before trading.","related":[["amm","Automated market maker (AMM)","An automated market maker (AMM) is a type of DEX that prices trades with a mathematical formula based on the tokens held in a liquidity pool, instead of matching buyers and sellers in an order book."],["centralized-exchange","Centralized exchange (CEX)","A centralized exchange (CEX) is a company-run trading platform where you deposit funds into an account and trade crypto through the exchange's order book, with the company holding custody of your assets."],["liquidity-pool","Liquidity pool","A liquidity pool is a smart contract holding two or more tokens that traders swap against on a DEX, funded by liquidity providers who earn a share of the trading fees."],["slippage","Slippage","Slippage is the difference between the price you expect when you place a trade and the average price at which the trade actually fills, usually caused by thin liquidity or fast-moving markets."],["perp-dex","Perp DEX (on-chain perpetuals)","A perp DEX is a decentralized exchange for perpetual futures, letting you trade with leverage from your own wallet while margin, positions and settlement are handled on-chain or on a dedicated chain."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":"/compare","cta":false},"flash-loan":{"slug":"flash-loan","cat":"defi","en":"Flash loan","contentLocale":"en","term":"Flash loan","aka":["flash loans","uncollateralized loan"],"short":"A flash loan is an uncollateralized DeFi loan that must be borrowed and repaid, with a fee, within the same blockchain transaction, or the whole transaction is cancelled.","body":[["Smart contracts can bundle many steps into one transaction. A flash loan uses this: you borrow, use the funds, and repay in a single transaction. If repayment fails, the ",["blockchain","blockchain"]," reverts everything, so the lender is never at risk of default. Aave popularised flash loans, and other protocols offer similar features."],["Legitimate uses include ",["arbitrage","arbitrage"]," between DEXs, refinancing a loan from one protocol to another, and swapping collateral without first closing a position. They require writing or using a ",["smart contract","smart-contract"],", so they are a developer and bot tool rather than something you request from an app."],"Flash loans are also used in attacks. They give attackers temporary access to large capital to manipulate a thinly traded pool or a weak oracle. The weakness is usually in the targeted protocol's design, not in the flash loan itself."],"example":["Suppose a token trades at 1.00 ",["USDC","usdc"]," on ",["DEX","dex"]," A and 1.02 USDC on DEX B. A bot flash-borrows 500,000 USDC, buys about 500,000 tokens on DEX A, sells them on DEX B for about 509,000 USDC after price impact, repays 500,000 USDC plus a 0.05 percent fee of 250 USDC, and keeps roughly 8,750 USDC before gas. If prices moved and the bot could not repay, the transaction would revert."],"mistakes":["Believing a flash loan lets an ordinary user borrow money for days without collateral.","Blaming flash loans for exploits that were really caused by manipulable oracles.","Paying for a flash loan bot or service advertised on social media, which is a common scam."],"faq":[{"q":"Can anyone take a flash loan?","a":"Anyone who can deploy or call a suitable smart contract can. There is no credit check, but you need technical skill."},{"q":"Are flash loans legal?","a":"Flash loans are a standard DeFi feature. Using them to exploit protocols may be treated as illegal depending on the jurisdiction and the circumstances."}],"title":"What is a flash loan? Meaning and uses in DeFi","description":"What a flash loan is, how it is borrowed and repaid in one transaction, and why it appears in arbitrage and exploits.","related":[["defi-lending","DeFi lending","DeFi lending is borrowing and lending crypto through smart contracts, where lenders earn interest from a shared pool and borrowers must lock more collateral than they borrow."],["oracle","Blockchain oracle","A blockchain oracle is a service that brings outside data, most often asset prices, onto a blockchain so smart contracts can use it for actions like liquidations, settlements and swaps."],["mev","MEV (maximal extractable value)","MEV, or maximal extractable value, is the profit that block producers and specialised bots can make by choosing, inserting or reordering transactions inside a block, often at the expense of ordinary users."],["smart-contract","Smart contract","A smart contract is a program stored on a blockchain that runs automatically when its conditions are met, letting people trade, lend or issue tokens without a middleman."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"wrapped-token":{"slug":"wrapped-token","cat":"defi","en":"Wrapped token","contentLocale":"en","term":"Wrapped token","aka":["wrapped asset","WBTC","WETH"],"short":"A wrapped token is a token on one blockchain that represents another asset one-to-one, such as WBTC representing bitcoin on Ethereum, backed by the original asset held by a custodian or smart contract.","body":[[["Bitcoin","bitcoin"]," cannot run ",["Ethereum","ethereum"]," smart contracts. To use BTC in Ethereum ",["DeFi","defi"],", a custodian or protocol holds real BTC and issues an ERC-20 token, such as WBTC or cbBTC, for each BTC held. To unwrap, the token is burned and the BTC released."],["Some wrapping is simpler. WETH wraps native ETH into an ERC-20 token on Ethereum itself, through a ",["smart contract","smart-contract"]," with no custodian, so apps can treat ETH like other tokens. Bridged tokens on other chains are also a form of wrapped asset."],"The value of a wrapped token depends on its backing and the ability to redeem it. If the custodian, bridge or contract fails, the wrapped token can trade below the original asset. Check who holds the reserves and whether they publish proof of them."],"example":["Say you hold 0.5 BTC and want to use it as collateral on Ethereum. You exchange it for 0.5 WBTC, which a custodian backs with 0.5 BTC. You deposit the WBTC in a lending protocol and borrow ",["stablecoins","stablecoin"],". Months later, you repay, withdraw your 0.5 WBTC and ",["convert","instant-convert"]," it back to native BTC. If the wrapped token had lost its backing in the meantime, it could have been worth far less than 0.5 BTC."],"mistakes":["Assuming a wrapped token carries no risk beyond the price of the original asset.","Sending a wrapped token to an address on the original chain, for example WBTC to a Bitcoin address.","Confusing different wrapped versions of the same asset that are not interchangeable."],"faq":[{"q":"Is WBTC the same as BTC?","a":"WBTC tracks BTC one-to-one but is an Ethereum token backed by BTC held by a custodian. It adds custodian and smart contract risk."},{"q":"Why do I need WETH?","a":"Some DeFi apps require tokens in ERC-20 format. WETH converts ETH into that format one-to-one and can be unwrapped at any time."}],"title":"What is a wrapped token? WBTC and WETH explained","description":"What wrapped tokens like WBTC and WETH are, how wrapping and unwrapping works, and the backing risk to check.","related":[["cross-chain-bridge","Cross-chain bridge","A cross-chain bridge is a protocol that moves tokens or messages between two blockchains, usually by locking or burning assets on one chain and releasing or minting matching assets on the other."],["liquid-staking","Liquid staking","Liquid staking is a way to stake coins through a protocol that issues a tradable token, such as stETH, representing your staked position, so you earn staking rewards and can still use or sell the token."],["coin-vs-token","Coin vs token","A coin is the native asset of its own blockchain, such as BTC or ETH, while a token is an asset created on top of an existing blockchain using a smart contract, such as USDT on Ethereum."],["depeg","Depeg","A depeg is when a stablecoin or pegged token trades meaningfully away from the value it is designed to track, such as a dollar stablecoin falling below 1 USD."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"kyc":{"slug":"kyc","cat":"regulation","en":"KYC (know your customer)","contentLocale":"en","term":"KYC (know your customer)","aka":["KYC","know your customer","identity verification"],"short":"KYC (know your customer) is the identity check that regulated exchanges and financial firms run before letting you deposit, trade or withdraw, usually with an ID document and a selfie.","body":[["KYC is part of ",["anti-money laundering","aml"]," rules. A typical crypto exchange asks for your name, date of birth and country, a photo of a passport or national ID, and a live selfie or video check. Higher levels may require proof of address or proof of where your funds come from."],["Exchanges often tie features to verification levels. Without completed KYC you may only be able to view the app, or you may face low withdrawal limits. Fiat deposits, futures, ",["P2P trading","p2p-trading"]," and higher limits usually require full verification. Exactly what is required depends on the exchange and on rules in your country."],"KYC data is sensitive, so think about who receives it. Only complete verification on the exchange's official app or website, never through links sent by messages or third parties. Exchanges usually use specialist identity providers, and reputable ones explain this in their privacy policy. If an account was verified with someone else's documents, it can be frozen."],"example":["Suppose an exchange lets unverified users withdraw nothing, basic-verified users withdraw up to 2 ",["BTC","bitcoin"]," per day, and advanced-verified users up to 100 BTC per day. You complete basic KYC with your ID and a selfie and want to move 3 BTC to a ",["hardware wallet","hardware-wallet"],". You could send 2 BTC today and 1 BTC tomorrow, or complete the advanced level with proof of address to move all 3 BTC at once. These limits are illustrative; each exchange sets its own."],"mistakes":["Uploading ID documents through a link sent in a chat or email instead of the official app.","Letting a friend or broker verify an account for you, which breaks exchange terms and can freeze funds.","Depositing a large amount before checking whether your verification level allows you to withdraw it."],"faq":[{"q":"Why do crypto exchanges require KYC?","a":"Regulated exchanges must verify users under anti-money laundering and counter-terrorist financing rules. KYC also helps exchanges recover accounts and comply with sanctions."},{"q":"How long does KYC take on an exchange?","a":"Basic checks often finish within minutes, while manual reviews or advanced levels can take hours or days. It depends on the exchange and how clear your documents are."}],"title":"What is KYC in crypto? Know your customer explained","description":"What KYC means on crypto exchanges, which documents are usually required, how verification levels work and how to submit ID safely.","related":[["aml","AML (anti-money laundering)","AML (anti-money laundering) is the set of laws and internal controls that financial firms, including crypto exchanges, use to detect and prevent illegal funds from entering the system."],["travel-rule","Travel rule","The travel rule is an anti-money laundering requirement that makes crypto service providers share sender and recipient information when they transfer crypto for customers."],["no-kyc-exchange","No-KYC exchange","A no-KYC exchange is a platform that lets you trade crypto without verifying your identity, either fully or up to certain withdrawal limits."],["centralized-exchange","Centralized exchange (CEX)","A centralized exchange (CEX) is a company-run trading platform where you deposit funds into an account and trade crypto through the exchange's order book, with the company holding custody of your assets."],["vasp","VASP (virtual asset service provider)","A VASP (virtual asset service provider) is a business that exchanges, transfers, holds or manages crypto for customers and must follow anti-money laundering rules where it operates."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"How does KYC work, and who should get your ID?"},"coin":null,"tool":null,"cta":false},"demo-trading":{"slug":"demo-trading","cat":"exchange-features","en":"Demo trading","contentLocale":"en","term":"Demo trading","aka":["paper trading","demo account","simulated trading","testnet trading"],"short":"Demo trading is practising on an exchange with virtual funds in a simulated account, so you can learn order types, leverage and futures mechanics without risking real money.","body":[["Many exchanges, including OKX, Bybit and Bitget, offer a demo mode with virtual balances such as tens of thousands of virtual ",["USDT","usdt"],". Some run on a testnet with separate prices, while others mirror live market prices more closely. Orders, positions, funding and ",["liquidation","liquidation"]," work like the real thing as far as possible."],["Demo trading is useful for learning the interface, testing how margin modes work, practising ",["stop loss","stop-loss"]," and ",["take profit","take-profit"]," placement, and checking a strategy's rules before using real funds. It is especially valuable before trying leveraged futures."],["Its limits matter. Fills can be more generous than in real markets, ",["liquidity","liquidity"]," and ",["slippage","slippage"]," may not match, and losing virtual money does not trigger the same emotions as real losses. Treat demo results as practice, then start small with real funds and the same rules."]],"example":"Suppose you start a demo account with 10,000 virtual USDT and open a BTC long at 50,000 USDT with 10x leverage, using 1,000 USDT margin for a 10,000 USDT position. You see that a 5% drop to 47,500 would erase 500 USDT, half your margin, and your liquidation price sits a little above 45,000, depending on maintenance margin. Practising this lets you choose a stop loss at 48,500, limiting the loss to about 300 USDT.","mistakes":["Assuming results from demo trading will carry over unchanged to a live account.","Using much larger leverage in demo than you would ever use with real money.","Skipping demo practice entirely before using unfamiliar futures features."],"faq":[{"q":"Is demo trading the same as real trading?","a":"It uses similar tools, but fills, slippage and emotions differ. It is good practice, not a guarantee of real results."},{"q":"Can I withdraw demo trading profits?","a":"No. Demo balances are virtual and cannot be withdrawn or converted to real funds."}],"title":"What is demo trading in crypto? Paper trading explained","description":"What crypto demo trading is, how virtual futures accounts work, what you can practise safely and why demo results differ from live.","related":[["perpetual-futures","Perpetual futures (perps)","Perpetual futures (perps) are futures contracts with no expiry date that use a periodic funding rate to keep their price close to the underlying spot price."],["leverage","Leverage","Leverage is using borrowed funds or margin to open a position larger than your own capital, which multiplies both profits and losses."],["copy-trading","Copy trading","Copy trading is an exchange feature that automatically mirrors another trader's positions in your own account, in proportion to the amount you allocate."],["position-sizing","Position sizing","Position sizing is deciding how much to put into a single trade so that, if your stop-loss is hit, you lose only a planned share of your account."]],"lesson":{"id":"E19","slug":"what-leverage-does","ep":19,"title":"10x leverage: more money, or more risk?"},"coin":null,"tool":null,"cta":true}});
